export class Clients {
  private readonly service = inject(ClientService);

  protected readonly clients = signal<Client[]>([]);
  protected readonly query = signal('');
  // Case-insensitive name filter; an empty query shows every client.
  protected readonly filteredClients = computed(() => {
    const q = this.query().trim().toLowerCase();
    const list = this.clients();
    return q ? list.filter((c) => c.name.toLowerCase().includes(q)) : list;
  });
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    email: [
      '',
      [
        Validators.required,
        Validators.email,
        // Validators.email accepts "a@b"; also require a dotted domain (matches the server rule).
        Validators.pattern(/^[^@\s]+@[^@\s]+\.[^@\s]+$/),
        Validators.maxLength(255),
      ],
    ],
  });

  constructor() {
    this.load();
  }

  protected onSearch(event: Event): void {
    this.query.set((event.target as HTMLInputElement).value);
  }

  protected showError(field: 'name' | 'email'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, email } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    this.service.create({ name: name.trim(), email: email.trim() }).subscribe({
      next: (created) => {
        this.clients.update((list) => [...list, created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the client. Please try again.');
        this.saving.set(false);
      },
    });
  }

  private load(): void {
    this.service.list().subscribe((list) => this.clients.set(list));
  }
}
// Shared per-spec data setup. Each spec's beforeEach RESETS then SEEDS via the app's /__test__
// endpoint — this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so a developer running its own spec sees the
// broken endpoint immediately instead of shipping it.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

